"""RSS 리더 워커.

stdin으로 {trigger, action, args, storage, now, ...}를 받고, feeds의 각 주소를 받아 RSS 2.0(과 RSS 1.0)·Atom을
파싱해 items 항목 하나를 통째로 다시 쓴다. 외부 패키지를 쓰지 않는다.

동작
- refresh(기본): 모든 피드를 새로 받는다.
- import_opml: args.opml(OPML 글)의 피드를 목록에 더하고 곧바로 모두 받는다.

받기 규칙
- 새로 받은 글을 전에 받은 글에 덧쌓아 피드마다 최근 PER_FEED개까지 남기고, 저장 항목 한도(STORAGE_BUDGET)를 넘으면 피드마다 같은 개수씩 줄인다.
- ETag와 Last-Modified를 피드 상태에 남겨 조건부로 요청한다. 304면 전에 받은 글을 그대로 둔다.
- 피드 주소 대신 사이트 주소를 넣으면 HTML의 <link rel="alternate">에서 피드를 찾아 resolved에 남긴다.
- 실패한 피드는 오류를 상태에 남기고 전에 받은 글은 그대로 둔다. 나머지 피드는 계속한다.
- 429/503의 Retry-After는 호스트 단위로 지킨다. 그 시각까지 같은 호스트의 피드는 부르지 않는다.
  쉬는 피드는 error 없이 retry_after만 남긴다(화면이 기기 시각으로 안내한다).
- 피드 목록에서 빠진 피드의 글과 상태는 버린다.
"""
import hashlib
import html
import json
import re
import sys
import threading
import urllib.error
import urllib.request
import xml.etree.ElementTree as ET
from datetime import datetime, timedelta, timezone
from email.utils import parsedate_to_datetime
from html.parser import HTMLParser
from urllib.parse import urljoin, urlsplit

PER_FEED = 200  # 피드가 내주는 글(보통 10~50개)에 지난 글을 덧쌓아 이만큼까지 남긴다.
STORAGE_BUDGET = 900 * 1024  # 저장 항목 하나는 1MiB까지다. 상태와 여유를 남긴다.
REQUEST_TIMEOUT = 15
RUN_DEADLINE = 45  # 워커 한 번은 60초까지다. 남는 시간으로 결과를 쓴다.
PARALLEL = 6
MAX_BYTES = 5 * 1024 * 1024
SUMMARY_LEN = 300
DEFAULT_RETRY_SECS = 3600
USER_AGENT = "KaleidoscopeRSSReader/1.1"
FEED_TYPES = ("application/rss+xml", "application/atom+xml", "application/rdf+xml", "application/feed+json")

TAG = re.compile(r"<[^>]*>")
SPACE = re.compile(r"\s+")
URL = re.compile(r"https?://\S+")


def iso(dt):
    return dt.astimezone(timezone.utc).strftime("%Y-%m-%dT%H:%M:%SZ")


def local(tag):
    return tag.rsplit("}", 1)[-1] if isinstance(tag, str) else ""


def child(el, *names):
    if el is None:
        return None
    for c in el:
        if local(c.tag) in names:
            return c
    return None


def text(el, *names):
    c = child(el, *names)
    return "" if c is None else "".join(c.itertext()).strip()


def parse_date(value):
    value = (value or "").strip()
    if not value:
        return None
    try:
        dt = parsedate_to_datetime(value)  # RFC 822 (RSS pubDate)
    except (TypeError, ValueError, IndexError):
        try:
            dt = datetime.fromisoformat(value.replace("Z", "+00:00"))  # RFC 3339 (Atom, dc:date)
        except ValueError:
            return None
    if dt.tzinfo is None:
        dt = dt.replace(tzinfo=timezone.utc)
    return iso(dt)


def summarize(value):
    # 본문은 HTML이거나 한 번 더 이스케이프된 HTML이다. 태그를 벗기고 한 줄로 줄인다.
    plain = TAG.sub(" ", html.unescape(TAG.sub(" ", value or "")))
    plain = SPACE.sub(" ", plain).strip()
    # 링크가 글의 절반을 넘으면 요약이 아니라 링크 목록이다(예: "Article URL: … Comments URL: …").
    if sum(len(u) for u in URL.findall(plain)) * 2 > len(plain):
        return ""
    return plain if len(plain) <= SUMMARY_LEN else plain[: SUMMARY_LEN - 1].rstrip() + "…"


def link_of(el):
    """RSS의 <link>글</link>와 Atom의 <link rel href/>를 모두 읽는다. alternate를 먼저 고른다."""
    fallback = ""
    for c in el:
        if local(c.tag) != "link":
            continue
        href = (c.get("href") or "".join(c.itertext())).strip()
        if not href:
            continue
        if c.get("rel", "alternate") == "alternate":
            return href
        fallback = fallback or href
    return fallback


def rss_fields(item):
    guid = text(item, "guid")
    link = link_of(item)
    if not link and guid.startswith(("http://", "https://")):
        link = guid
    return {
        "title": text(item, "title"),
        "link": link,
        "guid": guid,
        "date": parse_date(text(item, "pubDate", "date", "published", "updated")),
        "summary": text(item, "description", "summary", "encoded"),
    }


def atom_fields(entry):
    return {
        "title": text(entry, "title"),
        "link": link_of(entry),
        "guid": text(entry, "id"),
        "date": parse_date(text(entry, "published", "updated")),
        "summary": text(entry, "summary", "content"),
    }


class NotAFeed(ValueError):
    pass


def parse(data, feed_url, base_url):
    """feed_url은 글 id의 이름공간(사용자가 넣은 주소), base_url은 상대 링크를 풀 실제 피드 주소다."""
    try:
        root = ET.fromstring(data)
    except ET.ParseError as error:
        raise NotAFeed("XML을 읽지 못했습니다: %s" % error)
    kind = local(root.tag)
    if kind == "feed":
        title, nodes, fields = text(root, "title"), [c for c in root if local(c.tag) == "entry"], atom_fields
    elif kind in ("rss", "RDF"):
        channel = child(root, "channel")
        scope = channel if kind == "rss" and channel is not None else root
        title, nodes, fields = text(channel, "title"), [c for c in scope if local(c.tag) == "item"], rss_fields
    else:
        raise NotAFeed("RSS나 Atom 문서가 아닙니다 (뿌리 요소: %s)" % kind)

    items = []
    for node in nodes:
        f = fields(node)
        link = urljoin(base_url, f["link"]) if f["link"] else ""
        identity = f["guid"] or link or f["title"]
        if not identity:
            continue
        items.append({
            "id": hashlib.sha1((feed_url + "\n" + identity).encode("utf-8")).hexdigest()[:16],
            "feed": feed_url,
            "title": f["title"] or "(제목 없음)",
            "link": link,
            "date": f["date"],
            "summary": summarize(f["summary"]),
        })
    # 날짜가 있는 글을 최근순으로, 날짜가 없는 글은 문서 순서대로 뒤에 둔다(정렬은 안정적이다).
    items.sort(key=lambda e: e["date"] or "", reverse=True)
    return title, items


class FeedLinks(HTMLParser):
    """HTML 문서의 <link rel="alternate" type="application/rss+xml" href>를 모은다."""

    def __init__(self):
        super().__init__()
        self.found = []

    def handle_starttag(self, tag, attrs):
        if tag != "link":
            return
        a = {k.lower(): (v or "") for k, v in attrs}
        rels = a.get("rel", "").lower().split()
        if "alternate" in rels and a.get("type", "").lower().split(";")[0].strip() in FEED_TYPES and a.get("href"):
            self.found.append(a["href"].strip())


def discover(data, page_url):
    finder = FeedLinks()
    try:
        finder.feed(data.decode("utf-8", errors="replace"))
    except Exception:
        return None
    return urljoin(page_url, finder.found[0]) if finder.found else None


class NotModified(Exception):
    pass


def fetch(url, etag=None, last_modified=None):
    headers = {
        "User-Agent": USER_AGENT,
        "Accept": "application/rss+xml, application/atom+xml, application/xml;q=0.9, text/xml;q=0.9, */*;q=0.5",
    }
    if etag:
        headers["If-None-Match"] = etag
    if last_modified:
        headers["If-Modified-Since"] = last_modified
    try:
        with urllib.request.urlopen(urllib.request.Request(url, headers=headers), timeout=REQUEST_TIMEOUT) as response:
            data = response.read(MAX_BYTES + 1)
            validators = (response.headers.get("ETag"), response.headers.get("Last-Modified"))
            final = response.geturl()
    except urllib.error.HTTPError as error:
        if error.code == 304:
            raise NotModified()
        raise
    if len(data) > MAX_BYTES:
        raise ValueError("피드가 %dMB를 넘습니다" % (MAX_BYTES // (1024 * 1024)))
    return data, validators, final


def load(url, before):
    """피드 하나를 받는다. 돌려주는 값: ('ok', 제목, 글들, 상태 갱신) 또는 ('same', 상태 갱신)."""
    target = before.get("resolved") or url
    conditional = before.get("count")  # 남은 글이 없으면 304를 받아도 보일 것이 없다.
    try:
        data, (etag, modified), final = fetch(
            target, before.get("etag") if conditional else None, before.get("last_modified") if conditional else None)
    except NotModified:
        return ("same", {})
    try:
        title, items = parse(data, url, final)
        resolved = target if target != url else None
    except NotAFeed as not_feed:
        # 사이트 주소일 수 있다. 피드 링크를 찾아 한 번만 따라간다.
        found = discover(data, final)
        if not found or found == target:
            raise not_feed
        data, (etag, modified), final = fetch(found)
        title, items = parse(data, url, final)
        resolved = found
    return ("ok", title, items, {"etag": etag, "last_modified": modified, "resolved": resolved})


def fit(entries):
    """저장 항목 한도 안에 들도록 피드마다 같은 개수(가장 최근 것부터)만 남긴다."""
    def size(e):
        return len(json.dumps(e, ensure_ascii=False).encode("utf-8")) + 1

    by_feed = {}
    for e in entries:
        by_feed.setdefault(e["feed"], []).append(e)
    if sum(size(e) for e in entries) <= STORAGE_BUDGET:
        return entries
    sizes = {f: [size(e) for e in es] for f, es in by_feed.items()}

    def total(k):
        return sum(sum(s[:k]) for s in sizes.values())

    lo, hi = 0, max(len(s) for s in sizes.values())
    while lo < hi:  # total(k) ≤ 예산인 가장 큰 k
        mid = (lo + hi + 1) // 2
        lo, hi = (mid, hi) if total(mid) <= STORAGE_BUDGET else (lo, mid - 1)
    kept = {id(e) for es in by_feed.values() for e in es[:lo]}
    return [e for e in entries if id(e) in kept]


def retry_at(header, now):
    header = (header or "").strip()
    if header.isdigit():
        return now + timedelta(seconds=int(header))
    try:
        dt = parsedate_to_datetime(header)
        return dt if dt.tzinfo else dt.replace(tzinfo=timezone.utc)
    except (TypeError, ValueError, IndexError):
        return now + timedelta(seconds=DEFAULT_RETRY_SECS)


def host(url):
    return urlsplit(url).hostname or url


def describe(error):
    if isinstance(error, urllib.error.HTTPError):
        return "HTTP %d %s" % (error.code, error.reason)
    if isinstance(error, urllib.error.URLError):
        reason = error.reason
        if isinstance(reason, TimeoutError):
            return "시간 초과(%d초)" % REQUEST_TIMEOUT
        return "연결 실패: %s" % reason
    if isinstance(error, TimeoutError):
        return "시간 초과(%d초)" % REQUEST_TIMEOUT
    if isinstance(error, NotAFeed):
        return "%s. 피드 링크도 찾지 못했습니다" % error
    return "%s: %s" % (type(error).__name__, error)


def opml_feeds(source):
    """OPML의 outline[xmlUrl]을 {url, name}으로 읽는다. 폴더(중첩 outline)는 펼친다."""
    try:
        root = ET.fromstring(source.encode("utf-8"))
    except ET.ParseError as error:
        raise ValueError("OPML을 읽지 못했습니다: %s" % error)
    feeds = []
    for node in root.iter():
        if local(node.tag) != "outline":
            continue
        url = (node.get("xmlUrl") or node.get("xmlurl") or "").strip()
        if url.startswith(("http://", "https://")):
            feeds.append({"url": url, "name": (node.get("title") or node.get("text") or "").strip()})
    if not feeds:
        raise ValueError("OPML에서 피드(xmlUrl)를 찾지 못했습니다")
    return feeds


def refresh(feed_list, previous, now):
    old_entries = previous.get("entries") or []
    old_status = previous.get("feeds") or {}
    urls = list(dict.fromkeys(f["url"] for f in feed_list if f.get("url")))

    # 지난 실행이 남긴 Retry-After를 호스트 단위로 모은다.
    blocked = {}
    for url, status in old_status.items():
        until = status.get("retry_after")
        if until and until > iso(now):
            blocked[host(url)] = max(until, blocked.get(host(url), ""))

    results = {}
    gate = threading.Semaphore(PARALLEL)

    def run(url):
        with gate:
            before = old_status.get(url) or {}
            if host(before.get("resolved") or url) in blocked:
                results[url] = ("blocked",)
                return
            try:
                results[url] = load(url, before)
            except Exception as error:  # 한 피드의 실패가 다른 피드를 막지 않는다.
                if isinstance(error, urllib.error.HTTPError) and error.code in (429, 503):
                    until = iso(retry_at(error.headers.get("Retry-After"), now))
                    blocked[host(before.get("resolved") or url)] = until
                    results[url] = ("blocked",)
                else:
                    results[url] = ("error", describe(error))

    threads = [threading.Thread(target=run, args=(u,), daemon=True) for u in urls]
    for t in threads:
        t.start()
    deadline = datetime.now(timezone.utc) + timedelta(seconds=RUN_DEADLINE)
    for t in threads:
        t.join(max(0.0, (deadline - datetime.now(timezone.utc)).total_seconds()))

    entries, status, ok, failed = [], {}, 0, 0
    for url in urls:
        before = old_status.get(url) or {}
        kept = [e for e in old_entries if e.get("feed") == url]
        result = results.get(url, ("timeout",))
        base = {"title": before.get("title"), "checked_at": iso(now), "ok_at": before.get("ok_at"),
                "error": None, "retry_after": None, "etag": before.get("etag"),
                "last_modified": before.get("last_modified"), "resolved": before.get("resolved")}
        if result[0] == "ok":
            _, title, items, validators = result
            # 피드에서 밀려난 지난 글도 남긴다. 같은 글은 새로 받은 쪽을 쓴다.
            fresh = {e["id"] for e in items}
            items = sorted(items + [e for e in kept if e["id"] not in fresh],
                           key=lambda e: e["date"] or "", reverse=True)[:PER_FEED]
            entries += items
            status[url] = {**base, **validators, "title": title or before.get("title"), "ok_at": iso(now),
                           "count": len(items)}
            ok += 1
        elif result[0] == "same":
            entries += kept
            status[url] = {**base, "ok_at": iso(now), "count": len(kept)}
            ok += 1
        else:
            entries += kept
            if result[0] == "blocked":
                base["retry_after"] = blocked.get(host(before.get("resolved") or url))
            else:
                base["error"] = result[1] if result[0] == "error" else \
                    "이번 새로고침 시간(%d초) 안에 끝나지 않았습니다" % RUN_DEADLINE
            status[url] = {**base, "count": len(kept)}
            failed += 1

    entries.sort(key=lambda e: e["date"] or "", reverse=True)
    entries = fit(entries)
    for url in urls:
        status[url]["count"] = sum(1 for e in entries if e["feed"] == url)
    summary = {"feeds": len(urls), "ok": ok, "failed": failed, "items": len(entries)}
    return summary, {"entries": entries, "feeds": status, "updated_at": iso(now)}


def main():
    payload = json.loads(sys.stdin.buffer.read().decode("utf-8"))
    now = datetime.strptime(payload["now"], "%Y-%m-%dT%H:%M:%SZ").replace(tzinfo=timezone.utc)
    storage = payload.get("storage") or {}
    feeds = list(storage.get("feeds") or [])
    writes = {}
    result = {}

    if payload.get("action") == "import_opml":
        args = payload.get("args") or {}
        known = {f.get("url") for f in feeds}
        added = [f for f in opml_feeds(args.get("opml") or "") if f["url"] not in known]
        added = list({f["url"]: f for f in added}.values())
        feeds += added
        writes["feeds"] = feeds
        result["imported"] = len(added)

    summary, items = refresh(feeds, storage.get("items") or {}, now)
    writes["items"] = items
    result.update(summary)
    sys.stdout.buffer.write(json.dumps({"result": result, "set_storage": writes}, ensure_ascii=False).encode("utf-8"))
    sys.stdout.flush()


main()
